from pathlib import Path
import json, html
root=Path(__file__).resolve().parents[1]
catalog=json.loads((root/'Mozdulj.Maui/Resources/Raw/exercises.catalog.json').read_text())
rows=[dict(name=x['name'],cat=x['category'],regions=x['regions'],tools=x['equipment'],measure=x['measure'], target=x.get('targetSeconds') if x['measure']=='time' else '+'.join(str(z['count'])+' '+z['label'] for z in x.get('repTargets',[])), difficulty=x['difficulty']) for x in catalog['exercises']]
markup=r'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mozdulj! v1.0 – görgetéses gyakorlattár és alkalmazkodó kihívások</title>
<style>
:root{font-family:system-ui,Segoe UI,sans-serif;color:#29233f;background:#f4effa}*{box-sizing:border-box}body{margin:0}.shell{max-width:510px;margin:0 auto;background:linear-gradient(165deg,#fcf9ff,#f7f0fc);min-height:100dvh;box-shadow:0 5px 50px #43315c22;padding:20px 16px 80px}h1{margin:6px 0 2px;font-size:26px}h2{margin:12px 0;font-size:20px}small,.muted{color:#71677f}.logo{font-weight:800;color:#6e46a9;font-size:20px}nav{display:flex;gap:8px;margin:20px 0}nav button{flex:1}button,select,input{border:1px solid #e3d8f0;border-radius:13px;padding:11px;font:inherit;background:white;color:#3a2d55}button{cursor:pointer}button.active,.primary{background:#6c49af;color:white;border-color:#6c49af;font-weight:700}.row{display:flex;gap:10px;align-items:center}.grow{flex:1}.card{background:#fff;border:1px solid #eee4f5;border-radius:18px;padding:15px;margin:10px 0;box-shadow:0 4px 15px #50296d0c}.pill{font-size:11px;padding:4px 8px;border-radius:50px;background:#eee6fc;color:#6539a2;display:inline-block}.big{font-size:25px;font-weight:800;color:#6542a4}.bar{background:#e8def0;border-radius:20px;height:11px;overflow:hidden;margin:10px 0}.fill{background:linear-gradient(90deg,#8e66d1,#5f408f);height:100%;border-radius:20px}.control{display:grid;grid-template-columns:1fr 1fr;gap:8px}input{width:100%;margin:6px 0}.tiny{font-size:12px}#list{min-height:100px}#sentinel{text-align:center;padding:16px;color:#6d6680}.badge{display:flex;gap:8px;margin-top:10px}.tier{flex:1;background:#f3effb;text-align:center;border-radius:12px;padding:8px;font-size:11px}.tier.done{background:#dff6ed;color:#276b58}#xpSample{width:100%}.note{background:#f2e9fa;padding:11px;border-radius:12px;font-size:12px;line-height:1.5} .hidden{display:none!important}
</style></head><body><main class="shell"><div class="logo">✿ Mozdulj!</div><h1>Fokozatosan, saját tempódban</h1><p class="muted">v0.10 – önálló, offline képernyő-előnézet</p><nav><button id="catalogTab" class="active">Gyakorlattár</button><button id="rewardTab">Kihívások</button></nav>
<section id="catalogScreen"><h2>Gyakorlattár <span class="pill">132 gyakorlat</span></h2><div class="note">Kezdetben 12 elem látszik. A további kártyák görgetésre érkeznek, nem jön létre egyszerre 132 ábrarajzoló.</div><input id="search" placeholder="Keresés névre vagy testtájra…" aria-label="Gyakorlat keresése"><div class="control"><select id="category" aria-label="Mozgástípus"><option value="">Összes mozgástípus</option></select><select id="tool" aria-label="Eszköz"><option value="">Bármilyen eszköz</option></select></div><p id="count" class="muted tiny"></p><div id="list"></div><div id="sentinel">További gyakorlatok betöltése…</div></section>
<section id="rewardScreen" class="hidden"><h2>🔥 Streak és szintek</h2><div class="card"><span class="big">14 nap</span><p>🧊 2/3 freeze · a pontjaid soha nem csökkennek.</p><label for="xpSample" class="tiny">XP-szintlépcsők kipróbálása (előnézeti állapot)</label><input type="range" id="xpSample" min="0" max="10000" step="25" value="1500"><p id="levelText"></p><div class="bar"><div id="levelFill" class="fill"></div></div><p id="freezeText" class="muted tiny"></p></div><h2>Havi, személyre szabott jelvények</h2><p class="muted tiny">Három cél, mindegyik három fokozattal. A következő hónap az előző eredményhez igazodik.</p><div id="goals"></div><div class="card"><strong>A következő hónap példája</strong><p class="tiny">Ha a 10 aktív napos cél sikerült, 11 lesz a következő. Ha a 11 nap nem sikerült, 10-re mérséklődik.</p><button class="primary" id="simulate">Sikeres hónap szimulálása</button><p id="simulation" class="muted"></p></div></section></main>
<script>const exercises=__EXERCISES__;
const byId=id=>document.getElementById(id);
const categories=[...new Set(exercises.map(x=>x.cat))].sort();const tools=[...new Set(exercises.flatMap(x=>x.tools))].sort();
for(const c of categories)byId('category').add(new Option(c,c));for(const c of tools)byId('tool').add(new Option(c,c));
let filtered=exercises,visible=0;const batchSize=12;let busy=false;
function append(){if(busy)return;busy=true;try{const slice=filtered.slice(visible,visible+batchSize);const frag=document.createDocumentFragment();for(const e of slice){let card=document.createElement('article');card.className='card';let name=document.createElement('strong');name.textContent=e.name;card.append(name);let description=document.createElement('div');description.className='tiny muted';description.textContent=`${e.cat} · ${e.regions.join(', ')} · ${e.tools.length?e.tools.join(', '):'Eszköz nélkül'}`;card.append(description);const p=document.createElement('div');p.className='tiny';p.style.marginTop='8px';p.textContent=e.measure==='time'?`${e.target||45} mp`:e.target||'Ismétlésszám';card.append(p);frag.append(card)}byId('list').append(frag);visible+=slice.length;byId('count').textContent=`${visible} / ${filtered.length} megjelenítve`;byId('sentinel').textContent=visible<filtered.length?'Görgess tovább a következő 12 elemhez':'A lista végére értél.';}finally{busy=false}}
function refresh(){const q=byId('search').value.toLocaleLowerCase('hu').trim(),cat=byId('category').value,tool=byId('tool').value;filtered=exercises.filter(x=>(!cat||x.cat===cat)&&(!tool||x.tools.includes(tool))&&(!q||(x.name+' '+x.regions.join(' ')).toLocaleLowerCase('hu').includes(q)));visible=0;byId('list').replaceChildren();append()}
for(const id of ['search','category','tool'])byId(id).addEventListener(id==='search'?'input':'change',refresh);
const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting && !byId('catalogScreen').classList.contains('hidden') && visible<filtered.length)append()},{rootMargin:'160px'});observer.observe(byId('sentinel'));refresh();
function switchTo(reward){byId('catalogScreen').classList.toggle('hidden',reward);byId('rewardScreen').classList.toggle('hidden',!reward);byId('catalogTab').classList.toggle('active',!reward);byId('rewardTab').classList.toggle('active',reward)}byId('catalogTab').onclick=()=>switchTo(false);byId('rewardTab').onclick=()=>switchTo(true);
function levelThreshold(n){return 250*n+25*n*(n-1)}function freezeThreshold(n){return 500*n+50*n*(n-1)}
function updateXp(){const xp=+byId('xpSample').value;let step=0;while(levelThreshold(step+1)<=xp)step++;let freezes=0;while(freezeThreshold(freezes+1)<=xp)freezes++;const nextLevel=levelThreshold(step+1),start=levelThreshold(step);byId('levelText').textContent=`⭐ ${xp.toLocaleString('hu')} XP · ${step+1}. szint · következő szint: ${nextLevel.toLocaleString('hu')} XP`;byId('levelFill').style.width=100*(xp-start)/(nextLevel-start)+'%';byId('freezeText').textContent=`Következő freeze-mérföldkő: ${freezeThreshold(freezes+1).toLocaleString('hu')} XP`};byId('xpSample').oninput=updateXp;updateXp();
const goals=[{icon:'📅',name:'Mozgásnapok',count:7,target:10,unit:'aktív nap'},{icon:'🎯',name:'Vállfókusz',count:7,target:15,unit:'gyakorlat'},{icon:'🧰',name:'Gumiszalag használata',count:3,target:6,unit:'különböző nap'}];
for(const g of goals){const c=document.createElement('div');c.className='card';c.innerHTML=`<strong>${g.icon} ${g.name}</strong><p class="tiny muted">${g.count} / ${g.target} ${g.unit}</p><div class="bar"><div class="fill" style="width:${Math.min(100,g.count/g.target*100)}%"></div></div>`;const ts=[Math.ceil(g.target*.45),Math.ceil(g.target*.75),g.target];const row=document.createElement('div');row.className='badge';ts.forEach((v,i)=>{const b=document.createElement('span');b.className='tier'+(g.count>=v?' done':'');b.textContent=['🌱 Kezdő','✦ Közép','♛ Haladó'][i]+' · '+v;row.append(b)});c.append(row);byId('goals').append(c)}
let next=10;byId('simulate').onclick=()=>{next++;byId('simulation').textContent=`A sikeres ${next-1} napos hónap után a következő cél: ${next} aktív nap.`};
</script></body></html>'''
markup=markup.replace('__EXERCISES__',json.dumps(rows,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
(root/'docs/UI_v10_gyors_katalogus_es_kihivasok.html').write_text(markup)
print('HTML preview',len(markup),'bytes')
